const fs = require("fs");
const path = require("path");
const { convertBuildMapFile } = require("./buildmap-converter");

const projectRoot = path.resolve(__dirname, "..");
const inputPath = path.join(projectRoot, "docs", "BuildMap.json");
const outputPath = path.join(projectRoot, "miniprogram", "data", "buildings.generated.js");

function writeGeneratedData() {
  const result = convertBuildMapFile(inputPath);
  const content = [
    "// This file is generated by scripts/generate-buildings.js.",
    "// Source: docs/BuildMap.json (BuildMap source coordinates georeferenced to mini program map coordinates).",
    "const BUILDING_FEATURES = ",
    JSON.stringify(result.buildings, null, 2),
    ";\n",
    "const BUILDING_LANDMARK_POIS = ",
    JSON.stringify(result.landmarkPois, null, 2),
    ";\n",
    "module.exports = {",
    "  BUILDING_FEATURES,",
    "  BUILDING_LANDMARK_POIS,",
    "};",
    "",
  ].join("\n");

  fs.writeFileSync(outputPath, content, "utf8");
  return result;
}

if (require.main === module) {
  const result = writeGeneratedData();
  console.log(`Generated ${result.buildings.length} buildings and ${result.landmarkPois.length} landmark POIs.`);
  console.log(outputPath);
}

module.exports = {
  writeGeneratedData,
};
